<template><section class="memory"><header><button @click="$router.push('/personal/games')">← 游戏大厅</button><h1>记忆翻牌</h1><button @click="reset">重开</button></header><p>步数：{{ moves }}　配对：{{ matched/2 }}/8　{{ matched===16?'🎉 全部完成！':'' }}</p><div class="cards"><button v-for="(c,i) in cards" :key="i" :class="{shown:c.show||c.done}" @click="flip(i)">{{ c.show||c.done?c.icon:'?' }}</button></div></section></template>
<script setup lang="ts">import{ref}from'vue';const icons=['🐟','🐬','🐳','🐙','🦀','🐢','⭐','🪸'];const cards=ref<{icon:string,show:boolean,done:boolean}[]>([]),moves=ref(0),matched=ref(0);let lock=false,first=-1;function reset(){cards.value=[...icons,...icons].sort(()=>Math.random()-.5).map(icon=>({icon,show:false,done:false}));moves.value=matched.value=0;first=-1;lock=false}function flip(i:number){const c=cards.value[i];if(lock||c.show||c.done)return;c.show=true;if(first<0){first=i;return}moves.value++;if(cards.value[first].icon===c.icon){cards.value[first].done=c.done=true;matched.value+=2;first=-1}else{lock=true;const a=first;first=-1;setTimeout(()=>{cards.value[a].show=c.show=false;lock=false},650)}}reset()</script>
<style scoped>.memory{max-width:570px;margin:auto;text-align:center;padding:15px}.memory header{display:flex;justify-content:space-between;align-items:center}.memory button{border:1px solid var(--c-border);background:var(--c-bg-card);color:var(--c-text-2);border-radius:9px;padding:9px}.cards{display:grid;grid-template-columns:repeat(4,110px);gap:10px;justify-content:center;margin-top:25px}.cards button{height:110px;font-size:34px;background:linear-gradient(135deg,var(--c-purple),var(--c-cyan));color:white}.cards .shown{background:var(--c-bg-card)}.memory p{color:var(--c-text-2)}@media(max-width:520px){.cards{grid-template-columns:repeat(4,21vw)}.cards button{height:21vw}.memory header{flex-wrap:wrap}.memory h1{order:3;width:100%}}</style>
